// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MONEY_BOX} from "../src/MONEY_BOX.sol";

contract InvMutTest is Test {
    MONEY_BOX c;
    function setUp() public { c = new MONEY_BOX(); }
    function testFuzz_property(uint256 val1, uint256 val2) public {
        vm.assume(val1 <= type(uint256).max - val2);
        c.SetMinSum(val1);
        c.SetMinSum(val2);
        assertTrue(c.MinSum() == val2);
    }
}
